document.addEventListener('DOMContentLoaded',()=>{const animatedElements=document.querySelectorAll('.js-animate');const hamburger=document.querySelector('.hamburger-menu');const navMenu=document.querySelector('.main-nav');const navLinks=document.querySelectorAll('.main-nav ul li a');const header=document.querySelector('.main-header');const heroSection=document.getElementById('hero-section');const themeToggle=document.getElementById('theme-toggle');const themeIcon=themeToggle ? themeToggle.querySelector('i'): null;if(themeToggle){const currentTheme=localStorage.getItem('theme');if(currentTheme){document.documentElement.setAttribute('data-theme',currentTheme);if(currentTheme==='dark'){themeIcon.classList.remove('fa-moon');themeIcon.classList.add('fa-sun');}}themeToggle.addEventListener('click',()=>{let theme=document.documentElement.getAttribute('data-theme');if(theme==='dark'){document.documentElement.setAttribute('data-theme','light');localStorage.setItem('theme','light');themeIcon.classList.remove('fa-sun');themeIcon.classList.add('fa-moon');}else{document.documentElement.setAttribute('data-theme','dark');localStorage.setItem('theme','dark');themeIcon.classList.remove('fa-moon');themeIcon.classList.add('fa-sun');}});}const filterButtons=document.querySelectorAll('.filter-btn');const projectItems=document.querySelectorAll('.project-item');filterButtons.forEach(button=>{button.addEventListener('click',()=>{filterButtons.forEach(btn=>btn.classList.remove('active'));button.classList.add('active');const filterValue=button.getAttribute('data-filter');projectItems.forEach(item=>{const categories=(item.getAttribute('data-category')|| '').split(' ');if(filterValue==='all' || categories.includes(filterValue)){item.classList.remove('hidden');item.style.opacity='0';setTimeout(()=>item.style.opacity='1',50);}else{item.classList.add('hidden');}});});});const observerOptions={root: null,rootMargin: '0px',threshold: 0.1};const observer=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}});},observerOptions);animatedElements.forEach(element=>{observer.observe(element);});if(header && heroSection){const scrollTrigger=heroSection.offsetHeight-100;window.addEventListener('scroll',()=>{if(window.scrollY>=scrollTrigger){header.classList.add('scrolled');}else{header.classList.remove('scrolled');}});window.dispatchEvent(new Event('scroll'));}if(hamburger && navMenu){hamburger.addEventListener('click',()=>{const isActive=hamburger.classList.toggle('is-active');navMenu.classList.toggle('is-active');if(isActive){document.body.style.overflow='hidden';}else{document.body.style.overflow='';}});navLinks.forEach(link=>{link.addEventListener('click',()=>{if(window.innerWidth<768){hamburger.classList.remove('is-active');navMenu.classList.remove('is-active');document.body.style.overflow='';}});});}});